--
-- Name: prevent_update_historized_books(); Type: FUNCTION; Schema: public; Owner: rxlog
--

CREATE FUNCTION public.prevent_update_historized_books() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.reading_status in ('finished','abandoned') then
    raise exception 'Book % is historized (%). Updates not allowed.',
      old.id, old.reading_status;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.prevent_update_historized_books() OWNER TO rxlog;

